"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["5835"],{4828(e,n,i){i.r(n),i.d(n,{metadata:()=>s,default:()=>h,frontMatter:()=>a,contentTitle:()=>o,toc:()=>l,assets:()=>c});var s=JSON.parse('{"id":"SoftwareEngineering/microservices-deep-dive","title":"Microservices Deep Dive","description":"Once you\'ve decided microservices genuinely fit your situation (see file 09), this page covers the practical questions: how to draw service boundaries, how services should communicate, who owns what data, and how to handle transactions that span multiple services.","source":"@site/docs/SoftwareEngineering/10-microservices-deep-dive.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/microservices-deep-dive","permalink":"/Mindstack/docs/SoftwareEngineering/microservices-deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":10,"frontMatter":{"title":"Microservices Deep Dive","sidebar_label":"Microservices Deep Dive","sidebar_position":10},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Monolith vs Microservices","permalink":"/Mindstack/docs/SoftwareEngineering/monolith-vs-microservices"},"next":{"title":"Modular Monolith","permalink":"/Mindstack/docs/SoftwareEngineering/modular-monolith"}}'),r=i(4848),t=i(8453);let a={title:"Microservices Deep Dive",sidebar_label:"Microservices Deep Dive",sidebar_position:10},o="Microservices Deep Dive",c={},l=[{value:"Drawing Service Boundaries",id:"drawing-service-boundaries",level:2},{value:"Service Communication Patterns",id:"service-communication-patterns",level:2},{value:"Synchronous \u2014 Request/Response",id:"synchronous--requestresponse",level:3},{value:"Asynchronous \u2014 Messaging / Events",id:"asynchronous--messaging--events",level:3},{value:"Data Ownership",id:"data-ownership",level:2},{value:"Distributed Transactions \u2014 The Saga Pattern",id:"distributed-transactions--the-saga-pattern",level:2},{value:"API Gateway",id:"api-gateway",level:2},{value:"Service Discovery",id:"service-discovery",level:2},{value:"Handling Partial Failure",id:"handling-partial-failure",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,t.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"microservices-deep-dive",children:"Microservices Deep Dive"})}),"\n",(0,r.jsx)(n.p,{children:"Once you've decided microservices genuinely fit your situation (see file 09), this page covers the practical questions: how to draw service boundaries, how services should communicate, who owns what data, and how to handle transactions that span multiple services."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"drawing-service-boundaries",children:"Drawing Service Boundaries"}),"\n",(0,r.jsx)(n.p,{children:"The single hardest and most consequential decision in a microservices architecture \u2014 a wrong boundary is expensive to fix later, because it requires coordinated changes across teams and services, plus a data migration."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'Bad boundary: technical layers\n  A "Database Service," a "Business Logic Service," a "API Service"\n  This creates a distributed monolith \u2014 every request still has to\n  touch all three services in sequence, but now over the network\n  instead of in-process. You get all the cost of microservices with\n  none of the independent-deployability benefit.\n\nGood boundary: business capabilities (this maps directly onto\nBounded Contexts from file 07, Domain-Driven Design)\n  A "User Service" (owns identity, authentication, profile)\n  An "Order Service" (owns order lifecycle, line items)\n  A "Billing Service" (owns invoicing, payment processing)\n\n  Each service can be deployed, scaled, and understood independently,\n  because each owns a complete, coherent slice of business capability \u2014\n  not a horizontal slice of technical layers.\n'})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"A useful heuristic: \"does this service's team need to talk to\nanother team to ship a typical change?\"\n\n  If shipping a change to the Order Service usually requires the\n  Billing team's involvement too, the boundary is probably drawn\n  in the wrong place \u2014 Order and Billing might need to be one\n  service, or the specific piece causing the coupling needs to move.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"service-communication-patterns",children:"Service Communication Patterns"}),"\n",(0,r.jsx)(n.h3,{id:"synchronous--requestresponse",children:"Synchronous \u2014 Request/Response"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"   Order Service                    Inventory Service\n        \u2502                                    \u2502\n        \u2502  \u2500\u2500 POST /reserve-stock \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500>  \u2502\n        \u2502                                    \u2502  (processes request)\n        \u2502  <\u2500\u2500 200 OK { reserved: true } \u2500\u2500  \u2502\n        \u2502                                    \u2502\n\nThe caller waits for a response before continuing.\n"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Use when:"}),' the caller genuinely needs an immediate answer before it can proceed (e.g. "is this item in stock?" must be answered before checkout can continue).']}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Cost:"})," the caller is now coupled to the callee's availability \u2014 if the Inventory Service is down or slow, the Order Service's request is blocked too. This chains failure: a slow downstream service makes every upstream caller slow (or failing) as well."]}),"\n",(0,r.jsx)(n.h3,{id:"asynchronous--messaging--events",children:"Asynchronous \u2014 Messaging / Events"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'   Order Service              Message Queue           Inventory Service\n        \u2502                          \u2502                           \u2502\n        \u2502 \u2500\u2500 publish \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502                           \u2502\n        \u2502   "OrderPlaced"          \u2502                           \u2502\n        \u2502                          \u2502 \u2500\u2500 deliver \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502\n        \u2502                          \u2502    "OrderPlaced"          \u2502  (processes,\n        \u2502                          \u2502                           \u2502   eventually)\n        \u2502  (continues immediately, doesn\'t wait for Inventory)\n\nThe publisher doesn\'t wait for the consumer to process the message.\n'})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Use when:"})," the caller doesn't need an immediate response, and can tolerate the downstream effect happening slightly later (\"eventually consistent\" \u2014 see file 17). Order placement doesn't need to wait for the warehouse notification email to actually be sent."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Benefit:"})," decouples the services' availability \u2014 if the Inventory Service is temporarily down, messages queue up and get processed once it's back, rather than the Order Service's request failing outright."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Cost:"})," genuine added complexity \u2014 you now need message infrastructure (a queue/broker, see file 12), and reasoning about system behavior requires thinking in terms of eventual consistency rather than immediate consistency."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'Practical guideline: use synchronous calls for "I need this answer\nright now to proceed" (checking stock before confirming an order).\nUse asynchronous messaging for "this needs to happen, but not\nnecessarily before I respond to the user" (sending a confirmation\nemail, updating analytics, notifying a downstream reporting system).\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"data-ownership",children:"Data Ownership"}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.strong,{children:"Each service should own its own data exclusively \u2014 no other service should read from or write to it directly."})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Anti-pattern: shared database\n  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502  Order     \u2502   \u2502 Inventory  \u2502   \u2502 Billing    \u2502\n  \u2502  Service   \u2502   \u2502  Service   \u2502   \u2502 Service    \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n        \u2502                \u2502                \u2502\n        \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n                          \u2502\n                    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n                    \u2502  Shared    \u2502\n                    \u2502 Database   \u2502\n                    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n  This looks like microservices but behaves like a monolith with\n  extra network hops \u2014 a schema change for Billing can silently break\n  Order Service if it happens to read the same table. Services are\n  NOT actually independently deployable, because they share a data\n  contract none of them fully controls alone.\n\nCorrect pattern: database per service\n  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502  Order   \u2502   \u2502 Inventory  \u2502   \u2502 Billing    \u2502\n  \u2502  Service \u2502   \u2502  Service   \u2502   \u2502 Service    \u2502\n  \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510 \u2502   \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u2502   \u2502 \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u2502\n  \u2502 \u2502  DB  \u2502 \u2502   \u2502 \u2502  DB  \u2502   \u2502   \u2502 \u2502  DB  \u2502   \u2502\n  \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518 \u2502   \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2502   \u2502 \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n  If Order Service needs Inventory data, it asks the Inventory Service\n  (via its API), never queries Inventory's database directly. Each\n  service's internal schema is a private implementation detail it can\n  change freely, as long as its public API contract stays stable.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"distributed-transactions--the-saga-pattern",children:"Distributed Transactions \u2014 The Saga Pattern"}),"\n",(0,r.jsx)(n.p,{children:"In a monolith with one database, a multi-step operation is a single ACID transaction \u2014 it either fully succeeds or fully rolls back. Across microservices with separate databases, there is no single transaction spanning all of them. The Saga pattern is the standard answer."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"A Saga is a sequence of local transactions, each in a different\nservice, where each step publishes an event that triggers the next\nstep \u2014 and each step has a defined COMPENSATING action to undo it\nif a LATER step fails.\n\nExample: placing an order involves three services\n\n  Step 1: Order Service creates an order (status: pending)\n  Step 2: Payment Service charges the customer\n  Step 3: Inventory Service reserves stock\n\n  If Step 3 fails (out of stock):\n    Compensating action for Step 2: refund the payment\n    Compensating action for Step 1: cancel the order\n\n  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510  succeeds  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510  succeeds  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502 Create  \u2502 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502  Charge   \u2502 \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500> \u2502  Reserve    \u2502\n  \u2502 Order   \u2502            \u2502 Payment   \u2502            \u2502  Stock      \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518            \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518            \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2518\n                                                       \u2502 FAILS\n                                                       \u25BC\n                              \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510      \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n                              \u2502  Refund    \u2502<\u2500\u2500\u2500\u2500\u2500\u2502  (trigger     \u2502 \n                              \u2502  Payment   \u2502      \u2502 compensation) \u2502\n                              \u2514\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518      \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n                                   \u25BC\n                            \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n                            \u2502  Cancel     \u2502\n                            \u2502  Order      \u2502\n                            \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'Two coordination styles for a Saga:\n\nChoreography \u2014 each service listens for events and decides its own\nnext action, with no central coordinator\n  Order Service publishes "OrderCreated"\n  Payment Service listens, charges, publishes "PaymentCharged"\n  Inventory Service listens, reserves stock, publishes "StockReserved"\n  Simple for a small number of steps; becomes hard to trace ("what\'s\n  the overall flow?") as the number of participating services grows \u2014\n  the logic is scattered across every service\'s event handlers.\n\nOrchestration \u2014 a central Saga Orchestrator explicitly calls each\nservice in sequence and handles compensation logic\n  Clear, centralized view of the entire multi-step flow.\n  The orchestrator itself becomes a new component to build and\n  operate, and a potential single point of coordination failure\n  (though not necessarily a single point of DATA failure, since each\n  step\'s data still lives in its owning service).\n\nRule of thumb: choreography for 2-3 simple steps; orchestration once\na saga has several steps or complex conditional branching \u2014 the\nexplicit, centralized flow becomes worth its added component.\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"api-gateway",children:"API Gateway"}),"\n",(0,r.jsx)(n.p,{children:"A single entry point that sits in front of all microservices, handling cross-cutting concerns so individual services don't each need to reimplement them."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"       Clients (web, mobile, third-party)\n                    \u2502\n                    \u25BC\n            \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n            \u2502  API Gateway  \u2502   handles: auth, rate limiting,\n            \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   request routing, response\n                    \u2502            aggregation, TLS termination\n      \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n      \u25BC             \u25BC             \u25BC\n \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n \u2502  User    \u2502    \u2502  Order   \u2502    \u2502 Billing  \u2502\n \u2502 Service  \u2502    \u2502 Service  \u2502    \u2502 Service  \u2502\n \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Benefits:"})," clients talk to one stable endpoint instead of needing to know about every service's location; authentication/rate-limiting logic lives in one place instead of being duplicated across every service; can aggregate multiple service calls into one client-facing response, reducing round trips for the client."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Risk:"})," the gateway itself becomes a critical piece of infrastructure \u2014 if it goes down, everything behind it is unreachable, so it needs its own redundancy and careful operational attention (this connects to the load balancing and Nginx concepts in the DevOps course)."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"service-discovery",children:"Service Discovery"}),"\n",(0,r.jsx)(n.p,{children:"In a system where services are scaled up/down dynamically (especially under container orchestration \u2014 see the DevOps course's Kubernetes pages), a service can't simply hardcode \"call Inventory Service at 10.0.1.15\" \u2014 that IP changes as instances come and go."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Client-side discovery:\n  The caller queries a service registry directly, then picks an\n  instance and calls it.\n\nServer-side discovery (the more common pattern today, especially\nunder Kubernetes):\n  The caller calls a stable name (e.g. a Kubernetes Service \u2014 see\n  the DevOps course's Kubernetes workloads page); the platform's own\n  networking layer resolves that name to a currently-healthy instance\n  automatically, transparently to the caller.\n"})}),"\n",(0,r.jsx)(n.p,{children:"This is a solved problem in modern container orchestration platforms \u2014 Kubernetes Services provide this out of the box, which is one of the strongest practical arguments for running microservices on Kubernetes rather than building this infrastructure by hand."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"handling-partial-failure",children:"Handling Partial Failure"}),"\n",(0,r.jsx)(n.p,{children:"In a monolith, if the process is running, all its internal function calls work. In microservices, ANY of the services you depend on can be down, slow, or partially degraded \u2014 and your service needs to handle that without cascading into a total system failure."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Circuit Breaker pattern:\n  After a downstream service fails repeatedly, STOP calling it for a\n  cooldown period, failing fast instead of waiting for each call to\n  time out \u2014 protects both the caller (fast failure instead of\n  hanging) and the struggling downstream service (stops piling more\n  load onto something already failing).\n\n  CLOSED (normal) \u2192 too many failures \u2192 OPEN (fail fast, don't call)\n       \u25B2                                           \u2502\n       \u2502                cooldown expires           \u2502\n       \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 HALF-OPEN (try one test call) \u2518\n\nTimeouts:\n  Every network call to another service needs an explicit timeout \u2014\n  without one, a hung downstream service can hang your service\n  indefinitely, and that can cascade upstream through every caller\n  in the chain.\n\nRetries with backoff:\n  Transient failures (a brief network blip) are common and often\n  worth retrying \u2014 but always with exponential backoff and a retry\n  limit, never an unbounded retry loop that can amplify load onto an\n  already-struggling service.\n\nBulkheads:\n  Isolate resources (e.g. connection pools) per downstream dependency,\n  so one slow/failing dependency can't exhaust resources needed to\n  call OTHER, healthy dependencies \u2014 named after ship compartments\n  that contain flooding to one section instead of sinking the whole vessel.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:'Draw service boundaries around business capabilities (aligned with Bounded Contexts, file 07), never around technical layers \u2014 a "database service" or "business logic service" is a distributed monolith, not real microservices.'}),"\n",(0,r.jsx)(n.li,{children:"If two services frequently need to be deployed together to ship a single feature, that's a strong signal the boundary between them is drawn in the wrong place."}),"\n",(0,r.jsx)(n.li,{children:"Never let two services share a database directly \u2014 even if it seems convenient short-term, it silently re-couples services that were supposed to be independent."}),"\n",(0,r.jsx)(n.li,{children:"Use synchronous calls only when the caller genuinely can't proceed without an immediate answer; reach for asynchronous messaging for anything that can tolerate happening slightly later."}),"\n",(0,r.jsx)(n.li,{children:"Add circuit breakers, timeouts, and bounded retries to every inter-service call from the start \u2014 partial failure isn't an edge case in a distributed system, it's a routine occurrence you must design for."}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Draw service boundaries around business capabilities, informed by Bounded Contexts (file 07) \u2014 not around technical layers, which produces a distributed monolith."}),"\n",(0,r.jsx)(n.li,{children:'Synchronous (request/response) calls fit "I need this answer now"; asynchronous messaging fits "this should happen, but not necessarily before I respond" \u2014 each has real trade-offs in coupling and complexity.'}),"\n",(0,r.jsx)(n.li,{children:"Each service must own its data exclusively \u2014 no shared databases between services, or independent deployability is an illusion."}),"\n",(0,r.jsx)(n.li,{children:"The Saga pattern replaces cross-service ACID transactions with a sequence of local transactions plus compensating actions for rollback; choreography suits simple sagas, orchestration suits complex ones."}),"\n",(0,r.jsx)(n.li,{children:"An API Gateway centralizes cross-cutting concerns (auth, rate limiting, routing) for clients, at the cost of becoming critical shared infrastructure."}),"\n",(0,r.jsx)(n.li,{children:"Service discovery, circuit breakers, timeouts, and bounded retries are not optional extras \u2014 they're required for handling the partial failure that's routine in any distributed system."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>o});var s=i(6540);let r={},t=s.createContext(r);function a(e){let n=s.useContext(t);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),s.createElement(t.Provider,{value:n},e.children)}}}]);